63	// YAML scalars that contain `:`, `#`, `"`, `\`, or start with whitespace
64	// require quoting. Em-dash (U+2014) and other non-ASCII printables do not.
65	function escapeYamlScalar(s: string): string {
66	  if (s.length === 0) return JSON.stringify(s);
67	  if (/^\s/.test(s)) return JSON.stringify(s);
68	  if (/["\\:#]/.test(s)) return JSON.stringify(s);
69	  return s;
70	}
