91	/**
92	 * Build the canonical FR-file frontmatter block. Returned string includes
93	 * leading and trailing `---\n` delimiters and a trailing newline.
94	 *
95	 * Field ordering (both modes):
96	 *   title → milestone → status → archived_at → (id | tracker)
97	 *     → [needs_technical_review] → created_at → [changelog_category]
98	 *
99	 * Throws:
100	 *   - {@link InvalidFrontmatterInputError} when `spec.id` and `trackerBinding`
101	 *     mismatch the active mode (mode-none requires id; tracker mode forbids id).
102	 *   - {@link InvalidTrackerShapeError} when `trackerBinding` carries a `url`
103	 *     property (verbose `{ key, id, url }` shape forbidden per STE-110 AC-STE-110.2).
104	 */
105	export function buildFRFrontmatter(
106	  spec: FRFrontmatterInput,
107	  trackerBinding?: TrackerBinding,
108	  opts?: BuildFRFrontmatterOpts,
109	): string {
110	  if (trackerBinding && spec.id) {
111	    throw new InvalidFrontmatterInputError(
112	      "tracker mode forbids id: field — pass spec.id=undefined when trackerBinding is provided",
113	    );
114	  }
115	  if (!trackerBinding && !spec.id) {
116	    throw new InvalidFrontmatterInputError(
117	      "mode-none requires spec.id (fr_<ULID>) — pass trackerBinding when in tracker mode",
118	    );
119	  }
120	  if (trackerBinding && Object.prototype.hasOwnProperty.call(trackerBinding, "url")) {
121	    throw new InvalidTrackerShapeError(
122	      "verbose tracker shape forbidden per STE-110 AC-STE-110.2 — pass { key, id } only",
123	    );
124	  }
125	
126	  const lines: string[] = ["---"];
127	  lines.push(`title: ${escapeYamlScalar(spec.title)}`);
128	  lines.push(`milestone: ${spec.milestone}`);
129	  lines.push("status: active");
130	  lines.push("archived_at: null");
131	  if (spec.id) {
132	    lines.push(`id: ${spec.id}`);
133	  } else if (trackerBinding) {
134	    lines.push("tracker:");
135	    lines.push(`  ${trackerBinding.key}: ${trackerBinding.id}`);
136	  }
137	  if (opts?.needsTechnicalReview === true) {
138	    lines.push("needs_technical_review: true");
139	  }
140	  lines.push(`created_at: ${spec.createdAt}`);
141	  if (opts?.changelogCategory !== undefined) {
142	    lines.push(`changelog_category: ${opts.changelogCategory}`);
143	  }
144	  lines.push("---");
145	  return lines.join("\n") + "\n";
146	}
