148	/**
149	 * Frontmatter keys whose value is the literal word `undefined`, nested keys
150	 * included (`tracker.undefined`). Reads the file's own bytes rather than a
151	 * parsed object, because the shape this catches is a template that wrote the
152	 * word out — a parser would hand back the STRING "undefined" and lose which key
153	 * carried it.
154	 */
155	function frontmatterUndefinedKeys(frFilePath: string): string[] {
156	  let text: string;
157	  try {
158	    text = readFileSync(frFilePath, "utf-8");
159	  } catch {
160	    return []; // an unreadable file is the probe's to report, not this scan's
161	  }
162	  // Through the shared normalizer, not a local CRLF replace: a BOM'd file would
163	  // otherwise fail the opener match and read as "no frontmatter", and the
164	  // structural sweep in the suite exists to catch exactly that hand-roll.
165	  const m = /^---\n([\s\S]*?)\n---/.exec(normalizeFrontmatterSource(text));
166	  if (!m) return [];
167	  const out: string[] = [];
168	  let parent = "";
169	  for (const line of m[1]!.split("\n")) {
170	    const kv = /^(\s*)([A-Za-z0-9_.-]+)\s*:\s*(.*)$/.exec(line);
171	    if (!kv) continue;
172	    const [, indent, key, value] = kv as unknown as [string, string, string, string];
173	    const nested = indent.length > 0;
174	    if (!nested) parent = key;
175	    const name = nested ? `${parent}.${key}` : key;
176	    if (key === "undefined" || value.trim() === "undefined") out.push(name);
177	  }
178	  return out;
179	}

