135	/**
136	 * Thrown when the caller-supplied `{slug}` sanitizes to empty. Rendered by
137	 * the skill as an NFR-10 canonical-shape refusal (verdict / remedy /
138	 * context). Raising here rather than returning an empty string prevents
139	 * `feat/m19-` from ever reaching `git checkout -b`.
140	 */
141	export class EmptySlugError extends Error {
142	  readonly rawSlug: string;
143	  constructor(rawSlug: string) {
144	    super(
145	      `buildBranchProposal: slug "${rawSlug}" sanitized to empty; cannot render a branch name.\n` +
146	        `Remedy: press [e] at the prompt and supply a 2–4 word kebab-case slug using characters [a-z0-9-], or re-run after editing the FR title so the LLM can infer a cleaner slug.\n` +
147	        `Context: rawSlug="${rawSlug}", operation=buildBranchProposal`,
148	    );
149	    this.name = "EmptySlugError";
150	    this.rawSlug = rawSlug;
151	  }
152	}
