154	/** Strip-to-[a-z0-9-], collapse hyphen runs, trim leading/trailing hyphens. */
155	function sanitizeSlug(raw: string): string {
156	  const kept = raw
157	    .toLowerCase()
158	    .replace(/[^a-z0-9-]/g, "")
159	    .replace(/-+/g, "-")
160	    .replace(/^-+|-+$/g, "");
161	  return kept;
162	}
163	
164	/** Clamp to allowed type set; unknown → `feat` (AC-STE-64.13). */
165	function clampType(raw: string): string {
166	  const cleaned = raw.toLowerCase().replace(/[^a-z]/g, "");
167	  return ALLOWED_TYPES.has(cleaned) ? cleaned : "feat";
168	}
169	
170	/** Resolve the `{ticket-id}` substitution per context (AC-STE-64.7). */
171	function resolveTicketId(ctx: BranchProposalContext): string {
172	  if (ctx.trackerId) return ctx.trackerId.toLowerCase();
173	  if (ctx.shortUlid) return ctx.shortUlid.toLowerCase();
174	  return "";
175	}
176	
177	/**
178	 * Render a branch proposal from the template. Handles sanitization,
179	 * substitution, 60-char truncation clamp (slug-only), and NFR-10 refusal
180	 * on empty-post-sanitize slug.
181	 */
182	export function buildBranchProposal(ctx: BranchProposalContext): string {
183	  const cleanSlug = sanitizeSlug(ctx.slug);
184	  if (cleanSlug.length === 0) {
185	    throw new EmptySlugError(ctx.slug);
186	  }
187	  const cleanType = clampType(ctx.type);
188	  const ticketId = resolveTicketId(ctx);
189	  const milestone = milestoneBranchToken(ctx.milestone ?? "");
190	
191	  // Render with empty slug first to compute the slug budget.
192	  const renderedWithoutSlug = ctx.template
193	    .replace(/{type}/g, cleanType)
194	    .replace(/{N}/g, milestone)
195	    .replace(/{ticket-id}/g, ticketId)
196	    .replace(/{slug}/g, "");
197	
198	  const budget = MAX_BRANCH_LENGTH - renderedWithoutSlug.length;
199	  let finalSlug = cleanSlug;
200	  if (budget < cleanSlug.length) {
201	    finalSlug = cleanSlug.slice(0, Math.max(0, budget)).replace(/-+$/g, "");
202	    // Non-slug parts alone ate the budget. Truncating to empty would render
203	    // a malformed branch like `feat/m19-` — fail loud rather than hand a
204	    // trailing-hyphen branch name to `git checkout -b`.
205	    if (finalSlug.length === 0) {
206	      throw new EmptySlugError(ctx.slug);
207	    }
208	  }
209	
210	  return ctx.template
211	    .replace(/{type}/g, cleanType)
212	    .replace(/{N}/g, milestone)
213	    .replace(/{ticket-id}/g, ticketId)
214	    .replace(/{slug}/g, finalSlug);

